declare(strict_types=1);require_once __DIR__.'/_bootstrap.php';require_once __DIR__.'/_layout.php';$st=$pdo->prepare('SELECT * FROM saas_reseller_invoices WHERE reseller_company_id=? ORDER BY reference_month DESC,id DESC');$st->execute([RESELLER_COMPANY_ID]);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];$view=(int)($_GET['id']??0);$items=[];if($view){$st=$pdo->prepare("SELECT i.*,c.name AS client_name,m.name AS module_name FROM saas_reseller_invoice_items i INNER JOIN companies c ON c.id=i.client_company_id INNER JOIN saas_modules m ON m.id=i.module_id INNER JOIN saas_reseller_invoices f ON f.id=i.invoice_id WHERE i.invoice_id=? AND f.reseller_company_id=? ORDER BY c.name,m.name,i.item_type");$st->execute([$view,RESELLER_COMPANY_ID]);$items=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}revenda_layout_start('Faturas da Nexa','faturas',$reseller);?><div class="warn">Estas faturas reúnem somente o custo mensal Nexa dos módulos ativos em todos os seus clientes. Não é adicionado valor de implantação. A cobrança dos clientes finais permanece sob responsabilidade da revenda.</div><div class="panel"><div class="table"><table><thead><tr><th>Competência</th><th>Vencimento</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=rev_h((string)$r['reference_month'])?></td><td><?=rev_h(rev_date_br($r['due_date'] ?? null))?></td><td><strong><?=rev_money((float)$r['amount'])?></strong></td><td><span class="pill"><?=rev_h((string)$r['status'])?></span></td><td><a class="btn btn-ghost" href="?id=<?=(int)$r['id']?>">Detalhar</a></td></tr><?php endforeach;?></tbody></table></div></div><?php if($view):?><div class="panel" style="margin-top:16px"><h2>Detalhamento</h2><div class="table"><table><thead><tr><th>Cliente</th><th>Módulo</th><th>Tipo</th><th>Valor</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=rev_h((string)$i['client_name'])?></td><td><?=rev_h((string)$i['module_name'])?></td><td><?=rev_h((string)$i['item_type'])?></td><td><?=rev_money((float)$i['total_amount'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?><?php revenda_layout_end();?>
